  "factorio": {"summary":"You will be mining resources, researching technologies, building infrastructure, automating production and fighting enemies. Use your imagination to design your factory, combine simple elements into ingenious structures, apply management skills to keep it working and finally protect it from the creatures who don't really like you.","themes":["Science fiction","Survival","Sandbox"],"gameModes":["Single player","Multiplayer","Co-operative"],"availability":["Switch 2","PC","Switch"],"stores":[{"label":"Nintendo eShop","url":"https://www.nintendo.com/store/products/factorio-switch/"},{"label":"Steam","url":"https://store.steampowered.com/app/427520"},{"label":"GOG","url":"https://www.gog.com/game/factorio"}],"media":["sct3fy","sct3fz","sct3ft","sct3fu","sct3fv","sct3fw"],"trailer":{"id":"KVvXv1Z6EY8","name":"Trailer"},"releaseDates":[{"platform":"PC","date":"Mar 10, 2013"},{"platform":"Switch","date":"Oct 28, 2022"},{"platform":"Switch 2","date":"Dec 22, 2025"}],"multiplayer":{"onlineMax":null,"onlineCoopMax":10000,"offlineCoopMax":null,"splitscreen":false,"campaignCoop":false},"engines":["Proprietary Engine"],"perspectives":["Bird view / Isometric"],"similar":[],"xbox":null,"nintendo":{"nsuid":"70010000056818","url":"https://www.nintendo.com/store/products/factorio-switch/","price":35,"regularPrice":35,"discounted":false,"currency":"USD","sizeGb":2.6,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition"]},"playstation":null,"steam":{"appId":"427520","url":"https://store.steampowered.com/app/427520","price":35,"regularPrice":35,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
  "ori-and-the-blind-forest": {"summary":"The forest of Nibel is dying. After a powerful storm sets a series of devastating events in motion, an unlikely hero must journey to find his courage and confront a dark nemesis to save his home. Ori and the Blind Forest tells the tale of a young orphan destined for heroics, through a visually stunning action-platformer crafted by Moon Studios for Xbox One and PC. Featuring hand-painted artwork, meticulously animated character performance, and a fully orchestrated score, Ori and the Blind Forest explores a deeply emotional story about love and sacrifice, and the hope that exists in us all.","themes":["Action","Fantasy","Thriller"],"gameModes":["Single player"],"availability":["PC","Xbox One","Switch"],"stores":[{"label":"Steam","url":"https://store.steampowered.com/app/261570"},{"label":"Xbox Store","url":"https://www.xbox.com/en-us/games/store/ori-and-the-blind-forest/c0mcc9r22kbj"}],"media":["qw0ciwlf01lqiutfg92c","sc5qkb","sc5qkf","sc5qkh","sc5qkc","sc5qkd"],"trailer":{"id":"cklw-Yu3moE","name":"Trailer"},"releaseDates":[{"platform":"PC","date":"Mar 11, 2015"},{"platform":"Xbox One","date":"Mar 11, 2015"},{"platform":"Switch","date":"Dec 20, 2020"}],"multiplayer":null,"engines":["Unity"],"perspectives":["Side view"],"similar":["little-nightmares"],"xbox":null,"nintendo":null,"playstation":null,"steam":null,"gamePassTiers":null,"playtime":null},
