  "silent-hill-f": {"summary":"Silent Hill f is a survival horror game published by Konami as part of the Silent Hill series. It is set in rural Japan during the 1960s, marking a departure from the franchise’s traditional Western settings. The story is written by Ryukishi07 and focuses on psychological horror, social pressure, and transformation.","themes":["Action","Horror"],"gameModes":["Single player"],"availability":["Xbox Series X|S","PC","PS5"],"stores":[{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/10010242"},{"label":"GOG","url":"https://www.gog.com/game/silent_hill_f"},{"label":"Xbox Store","url":"https://www.xbox.com/en-US/games/store/silent-hill-f/9nwtmtls2zpb"},{"label":"Steam","url":"https://store.steampowered.com/app/2947440"},{"label":"Epic Games","url":"https://store.epicgames.com/p/silent-hill-f-714aed"}],"media":["scvqot","scvqol","scvqos","scvqoo","scvqoq","scvqop"],"trailer":{"id":"v3r7QnKutko","name":"Teaser"},"releaseDates":[{"platform":"PC","date":"Sep 23, 2025"},{"platform":"PS5","date":"Sep 23, 2025"},{"platform":"Xbox Series X|S","date":"Sep 23, 2025"}],"multiplayer":null,"engines":["Unreal Engine 5"],"perspectives":["Third person"],"similar":["hollow-knight-silksong","little-nightmares-iii--1","hogwarts-legacy","blair-witch","alien-isolation","control","tunic"],"xbox":null,"nintendo":null,"playstation":{"productId":"JP0101-PPSA21159_00-MAINGAME00000000","conceptId":"10010242","url":"https://store.playstation.com/en-us/product/JP0101-PPSA21159_00-MAINGAME00000000","price":69.99,"regularPrice":69.99,"discounted":false,"currency":"USD","plusIncluded":false,"platforms":[],"editions":["Deluxe Edition","Standard Edition","Standard Dual Pack","Deluxe Dual Pack"],"sizeGb":null},"steam":{"appId":"2947440","url":"https://store.steampowered.com/app/2947440","price":39.99,"regularPrice":79.99,"discounted":true,"discountPercent":50,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
  "enshrouded": {"summary":"You are Flameborn, last ember of hope of a dying race. Awaken, survive the terror of a corrupting fog, and reclaim the lost beauty of your kingdom. Venture into a vast world, vanquish punishing bosses, build grand halls and forge your path in this co-op survival Action RPG for up to 16 players.","themes":["Action","Survival"],"gameModes":["Single player","Multiplayer","Co-operative"],"availability":["Xbox Series X|S","PC","PS5"],"stores":[{"label":"Steam","url":"https://store.steampowered.com/app/1203620/Enshrouded/"}],"media":["sc11ang","sc11anh","sc11ani","sc11anj","sc11ank","sc11anl"],"trailer":{"id":"qygf4aICf34","name":"Announcement Trailer"},"releaseDates":[{"platform":"PC","date":"Jan 24, 2024"},{"platform":"PS5","date":"Oct 15, 2026"},{"platform":"Xbox Series X|S","date":"TBD"}],"multiplayer":{"onlineMax":16,"onlineCoopMax":16,"offlineCoopMax":1,"splitscreen":false,"campaignCoop":true},"engines":["Holistic"],"perspectives":["Third person"],"similar":["torchlight-iii","remnant-from-the-ashes"],"xbox":null,"nintendo":null,"playstation":null,"steam":{"appId":"1203620","url":"https://store.steampowered.com/app/1203620","price":35.99,"regularPrice":39.99,"discounted":true,"discountPercent":10,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
