  "atomic-heart": {"summary":"Atomic Heart is an adventure first-person shooter, events of which unfolds in an alternate universe during the high noon of the Soviet Union. The principal character of the game is a special agent P-3, who after an unsuccessful landing on enterprise \"3826\" is trying to figure out what went wrong.","themes":["Action","Science fiction","Open world","Mystery"],"gameModes":["Single player"],"availability":["Xbox Series X|S","PS4","PC","PS5","Xbox One"],"stores":[{"label":"Xbox Store","url":"https://www.xbox.com/en-us/games/store/atomic-heart/9P731Z4BBCT3"},{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/10006316"},{"label":"Steam","url":"https://store.steampowered.com/app/668580"}],"media":["uttbnsozii22jvyscw0d","scahog","sctke8","btovpbevg3sny1v7tbxa","scahoj","kdibfssvgrekpigruiny"],"trailer":{"id":"AyHkMK3cT_c","name":"Trailer"},"releaseDates":[{"platform":"PS4","date":"Feb 21, 2023"},{"platform":"PC","date":"Feb 21, 2023"},{"platform":"PS5","date":"Feb 21, 2023"},{"platform":"Xbox One","date":"Feb 21, 2023"},{"platform":"Xbox Series X|S","date":"Feb 21, 2023"}],"multiplayer":null,"engines":["Unreal Engine 4"],"perspectives":["First person"],"similar":["high-on-life","outer-wilds","the-first-descendant"],"xbox":{"productId":"9N9KXP8RRPB5","url":"https://www.xbox.com/en-US/games/store/_/9N9KXP8RRPB5","price":59.99,"msrp":59.99,"onSale":false,"currency":"USD","sizeGb":158,"editions":["Atomic Heart (Windows)"],"optimizedFor":[],"compatibleWith":[],"capabilities":[]},"nintendo":null,"playstation":{"productId":"UP4133-PPSA10696_00-ATOMICHEARTULTIM","conceptId":"10006316","url":"https://store.playstation.com/en-us/product/UP4133-PPSA10696_00-ATOMICHEARTULTIM","price":109.99,"regularPrice":109.99,"discounted":false,"currency":"USD","plusIncluded":false,"platforms":[],"editions":["Gold Edition","Ultimate Edition","Standard"],"sizeGb":null},"steam":null,"gamePassTiers":null,"playtime":null},
  "xenoblade-chronicles-definitive-edition": {"summary":"Discover the origins of Shulk as he and his companions clash against a seemingly-unstoppable mechanical menace. Wield a future-seeing blade, chain together attacks, and carefully position your party members in strategic, real-time combat as you journey across a massive world.","themes":["Fantasy","Science fiction","Open world","Warfare"],"gameModes":["Single player"],"availability":["Switch"],"stores":[{"label":"Nintendo eShop","url":"https://www.nintendo.com/games/detail/xenoblade-chronicles-definitive-edition-switch/"}],"media":["sc82l1","sc82l4","sc6z07","sc82l2","sc82l3","ar4q10"],"trailer":{"id":"nLEkwIvfOO4","name":"Announcement Trailer"},"releaseDates":[{"platform":"Switch","date":"May 29, 2020"}],"multiplayer":null,"engines":[],"perspectives":["Third person"],"similar":["pokemon-legends-arceus","tales-of-arise","xenoblade-chronicles-2"],"xbox":null,"nintendo":{"nsuid":"70010000029711","url":"https://www.nintendo.com/games/detail/xenoblade-chronicles-definitive-edition-switch/","price":59.99,"regularPrice":59.99,"discounted":false,"currency":"USD","sizeGb":13.8,"platforms":["Nintendo Switch"],"compatibility":"Supported – Game behavior is consistent with Nintendo Switch.","editions":["Standard Edition","Physical Edition - US"]},"playstation":null,"steam":null,"gamePassTiers":null,"playtime":null},
