  "rise-of-the-ronin": {"summary":"Rise of the Rōnin is a combat focused open-world action RPG that takes place in Japan at a time of great change. It is the very end of a 300-year long Edo Period, commonly known as “Bakumatsu”. Set in the late 19th century, Japan is facing the darkest of times as it struggles with its oppressive rulers and deadly diseases while western influence permeates as civil war continues to rage between the Tokugawa Shogunate and the Anti-Shogunate factions.","themes":["Action","Historical"],"gameModes":["Single player","Multiplayer","Co-operative"],"availability":["PC","PS5"],"stores":[{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/10003386"},{"label":"Steam","url":"https://store.steampowered.com/app/1340990/Rise_of_the_Ronin/"}],"media":["scix68","scix69","scix6a","scix6c","scix6b","ar2ou6"],"trailer":{"id":"0gwsQvDGh4o","name":"Announcement Trailer"},"releaseDates":[{"platform":"PS5","date":"Mar 22, 2024"},{"platform":"PC","date":"Mar 10, 2025"}],"multiplayer":null,"engines":["Katana Engine"],"perspectives":["Third person"],"similar":["the-first-descendant","grounded"],"xbox":null,"nintendo":null,"playstation":{"productId":"UP9000-PPSA04539_00-RONINFULLGAME001","conceptId":"10003386","url":"https://store.playstation.com/en-us/product/UP9000-PPSA04539_00-RONINFULLGAME001","price":69.99,"regularPrice":69.99,"discounted":false,"currency":"USD","plusIncluded":true,"platforms":[],"editions":["Digital Deluxe Edition","Standard Edition"],"sizeGb":null},"steam":{"appId":"1340990","url":"https://store.steampowered.com/app/1340990","price":49.99,"regularPrice":49.99,"discounted":false,"discountPercent":0,"currency":"USD","sizeGb":null},"gamePassTiers":null,"playtime":null},
