  "friday-the-13th-the-game": {"summary":"Friday the 13th: The Game is a third-person horror, survival game where players take on the role of a teen counselor, or for the first time ever, Jason Voorhees. You and six other unlucky souls will do everything possible to escape and survive while the most well-known killer in the world tracks you down and brutally slaughters you.","themes":["Action","Horror","Survival","Stealth"],"gameModes":["Single player","Multiplayer","Co-operative"],"availability":["PS4","PC","Xbox One","Switch","Xbox Series X|S"],"stores":[{"label":"PlayStation Store","url":"https://store.playstation.com/en-us/concept/227121"},{"label":"Steam","url":"https://store.steampowered.com/app/438740"}],"media":["xb47daupycwqhjexiij1","fjltv7ivkju18iykyv9s","aptfhm1x8dq04d2mgyzp","dyozqcb9giqmdhbbg6zw","mij8i5vu54oczjo35ncm","ar4cu"],"trailer":{"id":"rUmkTGSyRA8","name":"Trailer"},"releaseDates":[{"platform":"PC","date":"May 25, 2017"},{"platform":"Xbox One","date":"May 26, 2017"},{"platform":"PS4","date":"May 26, 2017"},{"platform":"Switch","date":"Aug 13, 2019"}],"multiplayer":{"onlineMax":8,"onlineCoopMax":null,"offlineCoopMax":null,"splitscreen":false,"campaignCoop":false},"engines":["Unreal Engine 4"],"perspectives":["Third person"],"similar":["dead-by-daylight","scorn","metro-exodus"],"xbox":{"productId":"C0723XB6XJSX","url":"https://www.xbox.com/en-US/games/store/_/C0723XB6XJSX","price":null,"msrp":null,"onSale":false,"currency":"USD","sizeGb":9.3,"editions":[],"optimizedFor":["Xbox One"],"compatibleWith":["Xbox One","Xbox Series X|S"],"capabilities":[]},"nintendo":null,"playstation":{"productId":null,"conceptId":"227121","url":"https://store.playstation.com/en-us/concept/227121","price":null,"regularPrice":null,"discounted":false,"currency":"USD","plusIncluded":false,"platforms":[],"editions":[],"sizeGb":null},"steam":null,"gamePassTiers":null,"playtime":null},
